files.game.js:
const cv = document.getElementById('game');
const ctx = cv.getContext('2d');
const W = cv.width, H = cv.height, PW = 8, PH = 60, MB = 8;
const p = { l: {y: H / 2 - PH / 2}, r: {y: H / 2 - PH / 2} };
const ball = { x: W / 2, y: H / 2, vx: 3, vy: 2 };
let lScore = 0, rScore = 0, running = false;
const keys = {};

addEventListener('keydown', e => { keys[e.key] = true; });
addEventListener('keyup', e => { keys[e.key] = false; });

function reset() { ball.x = W / 2; ball.y = H / 2; ball.vx = 3 * (Math.random() < 0.5 ? -1 : 1); ball.vy = 2 * (Math.random() < 0.5 ? -1 : 1); running = true; }

function step() {
  if (keys['w']) p.l.y -= 5;
  if (keys['s']) p.l.y += 5;
  if (keys['ArrowUp']) p.r.y -= 5;
  if (keys['ArrowDown']) p.r.y += 5;
  p.l.y = Math.max(0, Math.min(H - PH, p.l.y));
  p.r.y = Math.max(0, Math.min(H - PH, p.r.y));
  if (!running) return;
  ball.x += ball.vx; ball.y += ball.vy;
  if (ball.y < 0 || ball.y > H) ball.vy *= -1;
  const hitL = ball.x - MB < PW && ball.y > p.l.y && ball.y < p.l.y + PH;
  const hitR = ball.x + MB > W - PW && ball.y > p.r.y && ball.y < p.r.y + PH;
  if (hitL || hitR) { ball.vx *= -1.06; ball.x = hitL ? PW + MB : W - PW - MB; }
  if (ball.x < 0) { rScore++; running = false; if (rScore >= 7) return; setTimeout(reset, 800); }
  if (ball.x > W) { lScore++; running = false; if (lScore >= 7) return; setTimeout(reset, 800); }
}

function draw() {
  ctx.fillStyle = '#14161b'; ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = '#262a33'; ctx.setLineDash([6, 6]); ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = '#f7f5ec';
  ctx.fillRect(0, p.l.y, PW, PH); ctx.fillRect(W - PW, p.r.y, PW, PH);
  ctx.fillStyle = '#b8f23a'; ctx.beginPath(); ctx.arc(ball.x, ball.y, MB, 0, Math.PI * 2); ctx.fill();
}

setInterval(() => {
  step(); draw();
  document.getElementById('score').textContent = lScore + ' — ' + rScore + (lScore >= 7 || rScore >= 7 ? '  (game over — press R)' : '');
}, 16);

addEventListener('keydown', e => { if (e.key === 'r' || e.key === 'R') { lScore = 0; rScore = 0; reset(); } });
reset();
